/* ---------- start the output folder and process uploaded media ---------- */
try {
  const { buildSync } = await import("esbuild");
  const common = { bundle: true, minify: true, format: "iife", target: "es2019", legalComments: "none" };
  buildSync({ ...common, entryPoints: [path.join(ROOT, "src/scene/main.js")], outfile: path.join(STATIC, "assets/js/scene.js") });
  // clean addresses (no .html): the fade between pages also handles /about, /ai-agents and so on
  const appSrc = fs.readFileSync(path.join(ROOT, "src/app/main.js"), "utf8")
    .replace('if (!/(\\.html?|\\/)$/.test(u.pathname)) return;', 'if (!/(\\.html?|\\/|\\/[^./]+)$/.test(u.pathname)) return;')
    .replace('const pageKey = (p) => p.replace(/index\\.html?$/, "");', 'const pageKey = (p) => p.replace(/(index)?\\.html?$/, "").replace(/\\/$/, "");');
  buildSync({ ...common, stdin: { contents: appSrc, resolveDir: path.join(ROOT, "src/app"), sourcefile: "main.js", loader: "js" }, outfile: path.join(STATIC, "assets/js/app.js") });
} catch (e) { console.warn("esbuild not available, using the committed bundles:", e.message); }
fs.rmSync(DIST, { recursive: true, force: true });
fs.cpSync(STATIC, DIST, { recursive: true, filter: (src) => !src.endsWith(".glb") });
// styles for the longer service copy (skipped if site.css already has them)
{ const cssFile = path.join(DIST, "assets/css/site.css"); const cur = fs.readFileSync(cssFile, "utf8");
  if (!cur.includes(".prose {")) fs.writeFileSync(cssFile, cur.replace(/\s*$/, "\n\n") + EXTRA_CSS + "\n"); }
// the About photo (Nov 2026). To use a different photo later, delete these two lines and put it in static/assets/img
fs.writeFileSync(path.join(DIST, "assets/img/syed-mateen-portrait.jpg"), Buffer.from(PORTRAIT_JPG, "base64"));
fs.writeFileSync(path.join(DIST, "assets/img/syed-mateen-portrait.webp"), Buffer.from(PORTRAIT_WEBP, "base64"));
